using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com/";

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential());
        return client.GetChatClient(DeploymentName).AsIChatClient();
    }

    public static ChatConfiguration CreateChatConfiguration(bool enableTelemetry = true)
    {
        IChatClient client = CreateChatClient();

        if (enableTelemetry)
        {
            client = new ChatClientBuilder(client)
                .UseOpenTelemetry()
                .Build();
        }

        return new ChatConfiguration(client);
    }

    public static TracerProvider BuildTelemetryProvider()
    {
        return Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddConsoleExporter()
            .Build();
    }

    public static IEvaluator[] GetQualityEvaluators()
    {
        var judgeChatClient = CreateChatClient();
        return
        [
            new CoherenceEvaluator(judgeChatClient),
            new RelevanceEvaluator(judgeChatClient),
            new FluencyEvaluator(judgeChatClient),
            new CompletenessEvaluator(judgeChatClient),
        ];
    }

    public static ReportingConfiguration CreateReportingConfiguration(
        string storagePath = "eval-results")
    {
        return new ReportingConfiguration(
            storageRootPath: storagePath,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: CreateChatConfiguration());
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI interactions are captured via OpenTelemetry traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static TracerProvider? _tracerProvider;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        _tracerProvider = EvalConfig.BuildTelemetryProvider();
    }

    [ClassCleanup]
    public static void Teardown()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task Chat_EmitsTrace()
    {
        var chatConfig = EvalConfig.CreateChatConfiguration(enableTelemetry: true);

        var response = await chatConfig.ChatClient.GetResponseAsync(
            "Respond with one word: hello");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Expected non-empty response from model.");
    }

    [TestMethod]
    public async Task Chat_MultiTurn_EmitsTraces()
    {
        var chatConfig = EvalConfig.CreateChatConfiguration(enableTelemetry: true);
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2 + 2?")
        };

        var response = await chatConfig.ChatClient.GetResponseAsync(messages);
        messages.AddMessages(response);
        messages.Add(new ChatMessage(ChatRole.User, "Now multiply that by 3."));

        var followUp = await chatConfig.ChatClient.GetResponseAsync(messages);

        Assert.IsNotNull(followUp);
        Assert.IsTrue(followUp.Text.Length > 0);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates model responses using LLM-as-judge metrics
/// (coherence, relevance, fluency, completeness).
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? _reportingConfig;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        _reportingConfig = EvalConfig.CreateReportingConfiguration();
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: "coach-greeting");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my daily productivity?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync();

        var results = scenario.GetEvaluationResults();
        foreach (var result in results)
        {
            if (result.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Metric '{result.Key}' scored {numericValue.Value}, expected >= 3.");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_FollowUp_MeetsQualityBar()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: "coach-follow-up");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "I feel overwhelmed with my workload. What should I do?")
        };

        var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync();

        var results = scenario.GetEvaluationResults();
        foreach (var result in results)
        {
            if (result.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Metric '{result.Key}' scored {numericValue.Value}, expected >= 3.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario across multiple configurations
/// and stores results side-by-side for comparison.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string[] Prompts =
    [
        "You are a helpful coaching assistant.",
        "You are an expert life coach. Be concise and actionable."
    ];

    [TestMethod]
    public async Task CompareSystemPrompts()
    {
        var userMessage = "How do I stay focused while working from home?";

        foreach (var (prompt, index) in Prompts.Select((p, i) => (p, i)))
        {
            var tag = $"prompt-variant-{index}";
            var reportingConfig = EvalConfig.CreateReportingConfiguration(
                storagePath: $"eval-results/{tag}");

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                scenarioName: $"compare-focus-{tag}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, prompt),
                new(ChatRole.User, userMessage)
            };

            var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
            scenario.Record(messages, response);

            await scenario.EvaluateAsync();

            var results = scenario.GetEvaluationResults();
            foreach (var result in results)
            {
                if (result.Value is NumericMetricValue numericValue)
                {
                    Console.WriteLine($"[{tag}] {result.Key}: {numericValue.Value}");
                }
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var userMessage = "Give me three tips for better sleep.";
        var temperatures = new[] { 0.2f, 0.8f };

        foreach (var temp in temperatures)
        {
            var tag = $"temp-{temp:F1}";
            var reportingConfig = EvalConfig.CreateReportingConfiguration(
                storagePath: $"eval-results/{tag}");

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                scenarioName: $"compare-sleep-{tag}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, "You are a helpful coaching assistant."),
                new(ChatRole.User, userMessage)
            };

            var options = new ChatOptions { Temperature = temp };
            var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(
                messages, options);
            scenario.Record(messages, response);

            await scenario.EvaluateAsync();

            var results = scenario.GetEvaluationResults();
            foreach (var result in results)
            {
                if (result.Value is NumericMetricValue numericValue)
                {
                    Console.WriteLine($"[{tag}] {result.Key}: {numericValue.Value}");
                }
            }
        }
    }
}

