using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com/";

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential());
        return client.GetChatClient(DeploymentName).AsIChatClient();
    }

    public static ChatConfiguration CreateChatConfiguration(bool enableTelemetry = true)
    {
        IChatClient client = CreateChatClient();

        if (enableTelemetry)
        {
            client = new ChatClientBuilder(client)
                .UseOpenTelemetry()
                .Build();
        }

        return new ChatConfiguration(client);
    }

    public static TracerProvider BuildTelemetryProvider()
    {
        return Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddConsoleExporter()
            .Build();
    }

    public static IEvaluator[] GetQualityEvaluators()
    {
        var judgeChatClient = CreateChatClient();
        return
        [
            new CoherenceEvaluator(judgeChatClient),
            new RelevanceEvaluator(judgeChatClient),
            new FluencyEvaluator(judgeChatClient),
            new CompletenessEvaluator(judgeChatClient),
        ];
    }

    public static ReportingConfiguration CreateReportingConfiguration(
        string storagePath = "eval-results")
    {
        return new ReportingConfiguration(
            storageRootPath: storagePath,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: CreateChatConfiguration());
    }
}

