using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI interactions are captured via OpenTelemetry traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static TracerProvider? _tracerProvider;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        _tracerProvider = EvalConfig.BuildTelemetryProvider();
    }

    [ClassCleanup]
    public static void Teardown()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task Chat_EmitsTrace()
    {
        var chatConfig = EvalConfig.CreateChatConfiguration(enableTelemetry: true);

        var response = await chatConfig.ChatClient.GetResponseAsync(
            "Respond with one word: hello");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Expected non-empty response from model.");
    }

    [TestMethod]
    public async Task Chat_MultiTurn_EmitsTraces()
    {
        var chatConfig = EvalConfig.CreateChatConfiguration(enableTelemetry: true);
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2 + 2?")
        };

        var response = await chatConfig.ChatClient.GetResponseAsync(messages);
        messages.AddMessages(response);
        messages.Add(new ChatMessage(ChatRole.User, "Now multiply that by 3."));

        var followUp = await chatConfig.ChatClient.GetResponseAsync(messages);

        Assert.IsNotNull(followUp);
        Assert.IsTrue(followUp.Text.Length > 0);
    }
}

