using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario across multiple configurations
/// and stores results side-by-side for comparison.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string[] Prompts =
    [
        "You are a helpful coaching assistant.",
        "You are an expert life coach. Be concise and actionable."
    ];

    [TestMethod]
    public async Task CompareSystemPrompts()
    {
        var userMessage = "How do I stay focused while working from home?";

        foreach (var (prompt, index) in Prompts.Select((p, i) => (p, i)))
        {
            var tag = $"prompt-variant-{index}";
            var reportingConfig = EvalConfig.CreateReportingConfiguration(
                storagePath: $"eval-results/{tag}");

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                scenarioName: $"compare-focus-{tag}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, prompt),
                new(ChatRole.User, userMessage)
            };

            var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
            scenario.Record(messages, response);

            await scenario.EvaluateAsync();

            var results = scenario.GetEvaluationResults();
            foreach (var result in results)
            {
                if (result.Value is NumericMetricValue numericValue)
                {
                    Console.WriteLine($"[{tag}] {result.Key}: {numericValue.Value}");
                }
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var userMessage = "Give me three tips for better sleep.";
        var temperatures = new[] { 0.2f, 0.8f };

        foreach (var temp in temperatures)
